package com.configmonitor.app;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.Base64;import java.nio.charset.StandardCharsets;
public class ParserTest {
 String id="11111111-2222-3333-4444-555555555555";
 @Test public void realityPreserved()throws Exception{JSONObject n=Parser.parse("vless://"+id+"@[2001:db8::1]:443?security=reality&sni=example.com&pbk=key&sid=abc&flow=xtls-rprx-vision#%D8%A2%D9%84%D9%85%D8%A7%D9%86");assertEquals("آلمان",n.getString("name"));JSONObject c=n.getJSONObject("config");assertEquals("key",c.getJSONObject("streamSettings").getJSONObject("realitySettings").getString("publicKey"));assertEquals("xtls-rprx-vision",c.getJSONObject("settings").getJSONArray("vnext").getJSONObject(0).getJSONArray("users").getJSONObject(0).getString("flow"));assertEquals("2001:db8::1",n.getString("host"));}
 @Test public void vmessUnicodeUrlSafe()throws Exception{String json="{\"add\":\"example.com\",\"port\":443,\"id\":\""+id+"\",\"ps\":\"آزمایش\",\"net\":\"ws\",\"path\":\"/abc\",\"tls\":\"tls\"}";JSONObject n=Parser.parse("vmess://"+Base64.getUrlEncoder().withoutPadding().encodeToString(json.getBytes(StandardCharsets.UTF_8)));assertEquals("آزمایش",n.getString("name"));assertEquals("/abc",n.getJSONObject("config").getJSONObject("streamSettings").getJSONObject("wsSettings").getString("path"));}
 @Test public void shadowsocksLegacyAndSip()throws Exception{String auth="aes-128-gcm:pass+word:extra";String enc=Base64.getEncoder().withoutPadding().encodeToString(auth.getBytes(StandardCharsets.UTF_8));JSONObject a=Parser.parse("ss://"+enc+"@example.com:8388#SS"),b=Parser.parse("ss://"+Base64.getEncoder().encodeToString((auth+"@example.com:8388").getBytes(StandardCharsets.UTF_8)));assertEquals("pass+word:extra",a.getJSONObject("config").getJSONObject("settings").getJSONArray("servers").getJSONObject(0).getString("password"));assertEquals(a.getJSONObject("config").toString(),b.getJSONObject("config").toString());}
 @Test public void xhttpExtra()throws Exception{JSONObject n=Parser.parse("vless://"+id+"@example.com:443?type=xhttp&security=tls&extra=%7B%22noGRPCHeader%22%3Atrue%7D");assertTrue(n.getJSONObject("config").getJSONObject("streamSettings").getJSONObject("xhttpSettings").getJSONObject("extra").getBoolean("noGRPCHeader"));}
 @Test public void hy2AndTuic()throws Exception{JSONObject h=Parser.parse("hy2://p%2Bass@example.com:443?obfs=salamander&obfs-password=secret&sni=example.org");assertEquals("singbox",h.getString("engine"));assertEquals("p+ass",h.getJSONObject("config").getString("password"));assertFalse(h.getJSONObject("config").getJSONObject("tls").getBoolean("insecure"));JSONObject t=Parser.parse("tuic://"+id+":password@example.com:443");assertEquals(id,t.getJSONObject("config").getString("uuid"));}
 @Test public void jsonDropsInbounds()throws Exception{JSONObject n=Parser.parse("{\"inbounds\":[{\"type\":\"tun\"}],\"outbounds\":[{\"type\":\"socks\",\"server\":\"example.com\",\"server_port\":1080}]}");assertFalse(n.getJSONObject("config").has("inbounds"));assertEquals("probe",n.getJSONObject("config").getString("tag"));}
 @Test(expected=IllegalArgumentException.class) public void rejectsMultipleOutbounds()throws Exception{Parser.parse("{\"outbounds\":[{\"type\":\"socks\"},{\"type\":\"direct\"}]}");}
 @Test(expected=IllegalArgumentException.class) public void rejectsDirect()throws Exception{Parser.parse("{\"protocol\":\"freedom\"}");}
 @Test(expected=IllegalArgumentException.class) public void rejectsUnknown()throws Exception{Parser.parse("ssr://abc");}
 @Test(expected=IllegalArgumentException.class) public void rejectsPlugins()throws Exception{Parser.parse("ss://aes-128-gcm:pass@example.com:8388?plugin=unknown");}
 @Test public void manualAddress()throws Exception{JSONObject n=Parser.address("google.com","","HTTPS");assertEquals("https://google.com",n.getString("raw"));assertEquals("direct",n.getString("engine"));assertEquals("pending",n.getString("state"));}
 @Test(expected=IllegalArgumentException.class) public void rejectsAddressCredentials()throws Exception{Parser.address("https://user:pass@example.com","","TCP");}
}
